package com.mixologybatch;

final class BatchEntry
{
	private final Potion potion;
	private final Station station;
	private final int inventorySlot;
	private final int stationOrdinal;
	private final int stationPosition;
	private final int stationTotal;

	BatchEntry(
		Potion potion,
		Station station,
		int inventorySlot,
		int stationOrdinal,
		int stationPosition,
		int stationTotal)
	{
		this.potion = potion;
		this.station = station;
		this.inventorySlot = inventorySlot;
		this.stationOrdinal = stationOrdinal;
		this.stationPosition = stationPosition;
		this.stationTotal = stationTotal;
	}

	Potion getPotion()
	{
		return potion;
	}

	Station getStation()
	{
		return station;
	}

	int getInventorySlot()
	{
		return inventorySlot;
	}

	int getStationOrdinal()
	{
		return stationOrdinal;
	}

	int getStationPosition()
	{
		return stationPosition;
	}

	int getStationTotal()
	{
		return stationTotal;
	}

	BatchEntry remap(Potion remappedPotion, int remappedInventorySlot)
	{
		return new BatchEntry(
			remappedPotion,
			station,
			remappedInventorySlot,
			stationOrdinal,
			stationPosition,
			stationTotal);
	}
}

package com.mixologybatch;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

final class BatchInventoryOverlay extends WidgetItemOverlay
{
	private static final Color FIRST_BATCH = new Color(80, 220, 255);
	private static final Color SECOND_BATCH = new Color(255, 210, 70);
	private static final Color THIRD_BATCH = new Color(255, 110, 230);

	private final MixologyBatchPlugin plugin;
	private final MixologyBatchConfig config;

	@Inject
	private BatchInventoryOverlay(MixologyBatchPlugin plugin, MixologyBatchConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!plugin.isInLab() || !config.showInventoryBatches())
		{
			return;
		}
		Potion potion = Potion.fromItemId(itemId);
		if (potion == null)
		{
			return;
		}
		int slot = widgetItem.getWidget().getIndex();
		BatchEntry entry = plugin.getCycleEntry(slot, potion);
		if (entry == null)
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		String text = "#" + (entry.getStationOrdinal() + 1);
		graphics.setFont(FontManager.getRunescapeSmallFont());
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, bounds.x + 3, bounds.y + 12);
		graphics.setColor(batchColor(entry.getStationOrdinal()));
		graphics.drawString(text, bounds.x + 2, bounds.y + 11);

		Guidance guidance = plugin.getGuidance();
		if (guidance.getPhase() == Guidance.Phase.PROCESSING
			&& guidance.getEntry() != null
			&& guidance.getEntry().getInventorySlot() == slot)
		{
			graphics.setColor(config.stationColor());
			graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
			graphics.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 3, bounds.height - 3);
		}
	}

	private static Color batchColor(int stationOrdinal)
	{
			switch (stationOrdinal)
		{
			case 0:
				return FIRST_BATCH;
			case 1:
				return SECOND_BATCH;
			default:
				return THIRD_BATCH;
		}
	}
}

package com.mixologybatch;

enum BatchMode
{
	REFILLING,
	PROCESSING,
	FINISHING_PARTIAL;

	boolean isRefilling()
	{
		return this == REFILLING;
	}

	boolean allowsRollingRefill()
	{
		return this == PROCESSING;
	}

	static BatchMode initialize(
		int inventoryPotionCount,
		int activeStationCount,
		int potionCapacity,
		boolean mixingActivity,
		boolean hasUnfinishedInventoryPotion)
	{
		int accountedPotionCount = inventoryPotionCount + activeStationCount;
		if (accountedPotionCount == 0 || mixingActivity)
		{
			return REFILLING;
		}
		if (accountedPotionCount < potionCapacity
			&& (hasUnfinishedInventoryPotion || activeStationCount > 0))
		{
			return FINISHING_PARTIAL;
		}
		return PROCESSING;
	}
}

package com.mixologybatch;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class BatchPanelOverlay extends OverlayPanel
{
	private static final Color ERROR = new Color(255, 90, 90);
	private static final Color COMPLETE = new Color(70, 255, 120);
	private static final Color EMPTY = new Color(150, 150, 150);
	private static final Color EXTRA = new Color(255, 175, 70);

	private final MixologyBatchPlugin plugin;
	private final MixologyBatchConfig config;

	@Inject
	private BatchPanelOverlay(MixologyBatchPlugin plugin, MixologyBatchConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panelComponent.setPreferredSize(new Dimension(270, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isInLab() || !config.showPanel())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder().text("Brains Off Mixology Helper").build());
		Guidance guidance = plugin.getGuidance();
		switch (guidance.getPhase())
		{
			case INVALID:
				addLine("Paused", guidance.getMessage(), ERROR);
				break;
			case EMPTY:
				addLine("No batch", guidance.getMessage(), ERROR);
				break;
			case MIXING:
				renderMixing(guidance);
				break;
			case PROCESSING:
				renderProcessing(guidance);
				break;
			case COMPLETE:
				addLine("Complete", "Deposit / reset", COMPLETE);
				addLine("Potions", plugin.getPlan().size() + "/" + plugin.getPlan().size(), COMPLETE);
				break;
			default:
		}
		renderBatchInventory();
		return super.render(graphics);
	}

	private void renderMixing(Guidance guidance)
	{
		BatchEntry entry = guidance.getEntry();
		addLine("Mix potion", (entry.getInventorySlot() + 1) + "/" + plugin.getPlan().size(), Color.WHITE);
		addLine(entry.getPotion().name(), entry.getPotion().getDisplayName(), Color.WHITE);
		addLine("Recipe", entry.getPotion().getRecipeSequence(), Color.WHITE);
		addLine("Later", "#" + (entry.getStationOrdinal() + 1) + " " + entry.getStation().getObjectName(), config.stationColor());
	}

	private void renderProcessing(Guidance guidance)
	{
		BatchEntry entry = guidance.getEntry();
		addLine("Station batch", (entry.getStationOrdinal() + 1) + "/3", config.stationColor());
		addLine(entry.getStation().getObjectName(), entry.getStation().getActionName(), config.stationColor());
		addLine("Potion", (entry.getStationPosition() + 1) + "/" + entry.getStationTotal() + "  " + entry.getPotion().name(), Color.WHITE);
		addLine("NEXT", guidance.getAction() == Guidance.Action.WAIT_STATION ? "Processing" : "Use station", config.stationColor());
	}

	private void renderBatchInventory()
	{
		BatchPlan plan = plugin.getPlan();
		if (!plan.isValid() || plan.size() == 0)
		{
			return;
		}

		panelComponent.getChildren().add(TitleComponent.builder().text("Batch inventory").build());
		int capacity = plugin.getCyclePotionCapacity();
		if (capacity < plan.size())
		{
			addLine(capacity + "/" + plan.size(), "potion slots available", EXTRA);
		}
		for (Potion potion : Potion.values())
		{
			int configured = plan.getConfiguredCount(potion);
			int current = plugin.getCurrentPotionCount(potion);
			if (configured == 0 && current == 0)
			{
				continue;
			}
			if (configured == 0)
			{
				addLine(Integer.toString(current), potion.name() + " extra", EXTRA);
				continue;
			}
			Color color = current == 0
				? EMPTY
				: current > configured ? EXTRA
				: current == configured ? COMPLETE : Color.WHITE;
			addLine(current + "/" + configured, potion.name() + " left", color);
		}
	}

	private void addLine(String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build());
	}
}

package com.mixologybatch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

final class BatchPlan
{
	static final int INVENTORY_SIZE = 28;

	private final List<BatchEntry> entries;
	private final String error;

	private BatchPlan(List<BatchEntry> entries, String error)
	{
		this.entries = entries;
		this.error = error;
	}

	static BatchPlan create(Map<Potion, Integer> counts, StationOrder stationOrder)
	{
		Station[] stations = stationOrder.getStations();
		List<List<Potion>> batches = new ArrayList<>(stations.length);
		for (int i = 0; i < stations.length; i++)
		{
			batches.add(new ArrayList<>());
		}

		int total = 0;
		for (Potion potion : Potion.values())
		{
			int count = counts.getOrDefault(potion, 0);
			if (count < 0)
			{
				return invalid("Potion counts cannot be negative.");
			}
			total += count;
			for (int copy = 0; copy < count; copy++)
			{
				batches.get(copy % stations.length).add(potion);
			}
		}

		if (total > INVENTORY_SIZE)
		{
			return invalid("Configured batch has " + total + " potions; reduce it to 28 or fewer.");
		}

		List<BatchEntry> result = new ArrayList<>(total);
		int slot = 0;
		for (int stationOrdinal = 0; stationOrdinal < stations.length; stationOrdinal++)
		{
			List<Potion> batch = batches.get(stationOrdinal);
			for (int position = 0; position < batch.size(); position++)
			{
				result.add(new BatchEntry(
					batch.get(position),
					stations[stationOrdinal],
					slot++,
					stationOrdinal,
					position,
					batch.size()));
			}
		}

		return new BatchPlan(Collections.unmodifiableList(result), null);
	}

	static BatchPlan defaultPlan()
	{
		EnumMap<Potion, Integer> counts = new EnumMap<>(Potion.class);
		counts.put(Potion.MMA, 3);
		counts.put(Potion.MML, 4);
		counts.put(Potion.AAM, 3);
		counts.put(Potion.ALA, 3);
		counts.put(Potion.LLL, 3);
		counts.put(Potion.MLL, 3);
		counts.put(Potion.ALL, 3);
		counts.put(Potion.MAL, 6);
		return create(counts, StationOrder.CRYSTALLISE_HOMOGENISE_CONCENTRATE);
	}

	private static BatchPlan invalid(String error)
	{
		return new BatchPlan(Collections.emptyList(), error);
	}

	boolean isValid()
	{
		return error == null;
	}

	String getError()
	{
		return error;
	}

	int size()
	{
		return entries.size();
	}

	BatchEntry get(int slot)
	{
		return entries.get(slot);
	}

	List<BatchEntry> getEntries()
	{
		return entries;
	}

	int getConfiguredCount(Potion potion)
	{
		int count = 0;
		for (BatchEntry entry : entries)
		{
			if (entry.getPotion() == potion)
			{
				count++;
			}
		}
		return count;
	}

	int getConfiguredCount(Station station, Potion potion)
	{
		int count = 0;
		for (BatchEntry entry : entries)
		{
			if (entry.getStation() == station && entry.getPotion() == potion)
			{
				count++;
			}
		}
		return count;
	}
}

package com.mixologybatch;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class BatchQueueOverlay extends OverlayPanel
{
	private static final Color PREVIOUS = new Color(145, 145, 145);
	private static final Color CURRENT = new Color(255, 215, 70);
	private static final Color NEXT = Color.WHITE;

	private final MixologyBatchPlugin plugin;
	private final MixologyBatchConfig config;

	@Inject
	private BatchQueueOverlay(MixologyBatchPlugin plugin, MixologyBatchConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panelComponent.setPreferredSize(new Dimension(190, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isInLab() || !config.showActionQueue())
		{
			return null;
		}
		if (plugin.getGuidance().getPhase() != Guidance.Phase.MIXING)
		{
			return null;
		}

		List<Potion> previous = plugin.getPreviousQueuePotions();
		List<Potion> upcoming = plugin.getUpcomingQueuePotions();
		if (previous.isEmpty() && upcoming.isEmpty())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder().text("Potion queue").build());
		int previousOffset = -previous.size();
		for (int index = 0; index < previous.size(); index++)
		{
			addPotion(Integer.toString(previousOffset + index), previous.get(index), PREVIOUS);
		}
		for (int index = 0; index < upcoming.size(); index++)
		{
			addPotion(index == 0 ? "NOW" : "+" + index, upcoming.get(index), index == 0 ? CURRENT : NEXT);
		}
		return super.render(graphics);
	}

	private void addPotion(String position, Potion potion, Color color)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(position)
			.leftColor(color)
			.right(potion.name() + "  " + potion.getRecipeSequence())
			.rightColor(color)
			.build());
	}
}

package com.mixologybatch;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

final class BatchSceneOverlay extends Overlay
{
	private static final Color VESSEL_COLOR = Color.WHITE;
	private static final Color COMPLETE_COLOR = new Color(0, 255, 90);
	private static final Color NEXT_RECIPE_COLOR = new Color(150, 150, 150);
	private static final int MARKER_OFFSET = -22;
	private static final int CURRENT_RECIPE_OFFSET = 0;
	private static final int NEXT_RECIPE_OFFSET = 20;

	private final Client client;
	private final MixologyBatchPlugin plugin;
	private final MixologyBatchConfig config;
	private final LabObjectResolver objects;
	private final ModelOutlineRenderer outliner;

	@Inject
	private BatchSceneOverlay(
		Client client,
		MixologyBatchPlugin plugin,
		MixologyBatchConfig config,
		LabObjectResolver objects,
		ModelOutlineRenderer outliner)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.objects = objects;
		this.outliner = outliner;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isInLab() || !config.showSceneGuidance())
		{
			return null;
		}

		Guidance guidance = plugin.getGuidance();
		if (guidance.getPhase() == Guidance.Phase.MIXING)
		{
			renderMixingRecipe(
				graphics,
				guidance.getEntry().getPotion(),
				plugin.getNextQueuedPotion());
			return null;
		}
		renderPermanentLeverMarkers(graphics);

		LabObject target;
		Color color;
		String label;
		switch (guidance.getAction())
		{
			case USE_STATION:
				target = guidance.getEntry().getStation().getLabObject();
				color = config.stationColor();
				label = stationLabel(guidance.getEntry(), false);
				break;
			case WAIT_STATION:
				target = guidance.getEntry().getStation().getLabObject();
				color = config.stationColor();
				label = stationLabel(guidance.getEntry(), true);
				break;
			case DEPOSIT:
				target = LabObject.CONVEYOR;
				color = COMPLETE_COLOR;
				label = "BATCH READY";
				break;
			default:
				return null;
		}

		drawTarget(graphics, target, label, color);
		return null;
	}

	private void renderPermanentLeverMarkers(Graphics2D graphics)
	{
		for (Component component : Component.values())
		{
			TileObject object = objects.find(component.getLever());
			if (object != null)
			{
				drawLabel(
					graphics,
					object,
					Character.toString(component.getCode()),
					component.getColor(),
					MARKER_OFFSET);
			}
		}
	}

	private void renderMixingRecipe(Graphics2D graphics, Potion potion, Potion nextPotion)
	{
		for (Component component : Component.values())
		{
			TileObject object = objects.find(component.getLever());
			if (object == null)
			{
				continue;
			}
			drawLabel(
				graphics,
				object,
				Character.toString(component.getCode()),
				component.getColor(),
				MARKER_OFFSET);

			String currentLabel = leverLabel(potion, component);
			if (currentLabel != null)
			{
				outliner.drawOutline(
					object,
					config.outlineWidth(),
					component.getColor(),
					config.outlineFeather());
				drawLabel(
					graphics,
					object,
					currentLabel,
					component.getColor(),
					CURRENT_RECIPE_OFFSET);
			}

			String nextLabel = nextPotion == null ? null : leverLabel(nextPotion, component);
			if (nextLabel != null)
			{
				drawLabel(
					graphics,
					object,
					nextLabel,
					NEXT_RECIPE_COLOR,
					NEXT_RECIPE_OFFSET);
			}
		}
		drawTarget(graphics, LabObject.MIXING_VESSEL, "4", VESSEL_COLOR);
	}

	static String leverLabel(Potion potion, Component target)
	{
		StringBuilder label = new StringBuilder();
		Component[] recipe = potion.getRecipe();
		for (int index = 0; index < recipe.length; index++)
		{
			if (recipe[index] != target)
			{
				continue;
			}
			if (label.length() > 0)
			{
				label.append(" / ");
			}
			label.append(index + 1);
		}
		return label.length() == 0 ? null : label.toString();
	}

	private void drawTarget(Graphics2D graphics, LabObject target, String label, Color color)
	{
		TileObject object = objects.find(target);
		if (object == null)
		{
			return;
		}
		outliner.drawOutline(object, config.outlineWidth(), color, config.outlineFeather());
		drawLabel(graphics, object, label, color, 0);
	}

	private static String stationLabel(BatchEntry entry, boolean active)
	{
		return (entry.getStationPosition() + 1) + "/" + entry.getStationTotal()
			+ " " + (active ? "PROCESS" : entry.getStation().getActionName().toUpperCase());
	}

	private void drawLabel(
		Graphics2D graphics,
		TileObject object,
		String text,
		Color color,
		int verticalOffset)
	{
		graphics.setFont(graphics.getFont().deriveFont(Font.BOLD, 16f));
		Point location = Perspective.getCanvasTextLocation(client, graphics, object.getLocalLocation(), text, 120);
		if (location == null)
		{
			return;
		}
		int y = location.getY() + verticalOffset;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, location.getX() + 1, y + 1);
		graphics.setColor(color);
		graphics.drawString(text, location.getX(), y);
	}
}

package com.mixologybatch;

import java.util.EnumMap;
import java.util.List;
import java.util.Map;

final class BatchStateResolver
{
	Guidance resolve(
		BatchPlan plan,
		CyclePlan cycle,
		boolean refilling,
		List<InventorySlot> inventory,
		Potion vesselPotion,
		int[] mixerSlots,
		Map<Station, Potion> activeStations,
		Guidance previousGuidance)
	{
		if (!plan.isValid())
		{
			return Guidance.invalid(plan.getError());
		}
		if (plan.size() == 0)
		{
			return Guidance.empty();
		}
		if (cycle == null || !cycle.isValid())
		{
			return Guidance.invalid(cycle == null ? "Start a new batch." : cycle.getError());
		}
		if (!cycle.containsPotionSlots(inventory))
		{
			return Guidance.invalid("A potion moved outside the projected batch; pull a lever to start a new cycle.");
		}
		if (activeStations.size() > 1)
		{
			return Guidance.invalid("More than one processing station contains a potion.");
		}

		if (refilling)
		{
			return resolveMixing(plan, cycle, inventory, vesselPotion, mixerSlots, activeStations);
		}
		return resolveProcessing(cycle, inventory, activeStations, previousGuidance);
	}

	private Guidance resolveMixing(
		BatchPlan plan,
		CyclePlan cycle,
		List<InventorySlot> inventory,
		Potion vesselPotion,
		int[] mixerSlots,
		Map<Station, Potion> activeStations)
	{
		if (!activeStations.isEmpty())
		{
			return Guidance.invalid("Collect the station potion before starting a new mixing cycle.");
		}

		int inventoryPotionCount = countPotions(inventory);
		int potionCapacity = cycle.getPotionCapacity();
		if (potionCapacity == 0)
		{
			return Guidance.invalid("Clear at least one inventory slot to start mixing.");
		}
		if (inventoryPotionCount >= potionCapacity)
		{
			return resolveProcessing(cycle, inventory, activeStations, Guidance.outside());
		}

		int nextSlot = cycle.firstEmptySlot(inventory);
		if (nextSlot < 0)
		{
			return Guidance.invalid("Clear an inventory slot reserved for the next potion.");
		}

		Potion expected = nextNeededPotion(plan, cycle, inventory, nextSlot);
		if (expected == null)
		{
			return Guidance.invalid("The configured recipe totals are already present; process or adjust the batch.");
		}

		if (vesselPotion != null)
		{
			BatchEntry entry = cycle.entryForSlot(nextSlot, vesselPotion);
			return Guidance.mixing(entry, MixStep.resolve(vesselPotion, mixerSlots, true));
		}

		BatchEntry entry = cycle.entryForSlot(nextSlot, expected);
		MixStep step = MixStep.resolve(expected, mixerSlots, false);
		if (step.getKind() == MixStep.Kind.INVALID)
		{
			// A mistaken lever must not replace the intended recipe with an error.
			// Keep the correct sequence visible and reconcile the actual potion once mixed.
			step = MixStep.resolve(expected, new int[]{0, 0, 0}, false);
		}
		return Guidance.mixing(entry, step);
	}

	private Guidance resolveProcessing(
		CyclePlan cycle,
		List<InventorySlot> inventory,
		Map<Station, Potion> activeStations,
		Guidance previousGuidance)
	{
		if (!activeStations.isEmpty())
		{
			Map.Entry<Station, Potion> active = activeStations.entrySet().iterator().next();
			BatchEntry previousEntry = previousGuidance == null ? null : previousGuidance.getEntry();
			if (previousEntry != null
				&& (previousGuidance.getAction() == Guidance.Action.USE_STATION
					|| previousGuidance.getAction() == Guidance.Action.WAIT_STATION))
			{
				if (previousEntry.getStation() != active.getKey()
					|| previousEntry.getPotion() != active.getValue())
				{
					return Guidance.invalid(
						"Wrong station: use " + previousEntry.getStation().getObjectName()
							+ " for " + previousEntry.getPotion().name() + ".");
				}
				return Guidance.processing(previousEntry, true);
			}

			BatchEntry recovered = recoverActiveEntry(cycle, inventory, active.getKey(), active.getValue());
			return Guidance.processing(recovered, true);
		}

		BatchEntry unfinished = firstUnfinishedEntry(cycle, inventory);
		if (unfinished != null)
		{
			return Guidance.processing(unfinished, false);
		}
		return Guidance.complete();
	}

	static BatchEntry firstUnfinishedEntry(CyclePlan cycle, List<InventorySlot> inventory)
	{
		if (cycle == null || !cycle.isValid())
		{
			return null;
		}
		for (int rank = 0; rank < cycle.size(); rank++)
		{
			int slot = cycle.slotAtRank(rank);
			InventorySlot actual = inventory.get(slot);
			if (actual.isPotion() && !actual.isFinished())
			{
				return cycle.entryAtRank(rank, actual.getPotion());
			}
		}
		return null;
	}

	private static BatchEntry recoverActiveEntry(
		CyclePlan cycle,
		List<InventorySlot> inventory,
		Station station,
		Potion potion)
	{
		for (int rank = 0; rank < cycle.size(); rank++)
		{
			BatchEntry candidate = cycle.entryAtRank(rank, potion);
			if (candidate.getStation() == station && inventory.get(candidate.getInventorySlot()).isEmpty())
			{
				return candidate;
			}
		}
		for (int rank = 0; rank < cycle.size(); rank++)
		{
			BatchEntry candidate = cycle.entryAtRank(rank, potion);
			if (candidate.getStation() == station)
			{
				return candidate;
			}
		}
		return cycle.entryAtRank(0, potion);
	}

	static Potion nextNeededPotion(
		BatchPlan plan,
		CyclePlan cycle,
		List<InventorySlot> inventory,
		int nextSlot)
	{
		BatchEntry nextEntry = cycle.entryForSlot(nextSlot, plan.get(0).getPotion());
		if (nextEntry == null)
		{
			return null;
		}
		Station station = nextEntry.getStation();
		EnumMap<Potion, Integer> present = new EnumMap<>(Potion.class);
		for (int rank = 0; rank < cycle.size(); rank++)
		{
			int inventorySlot = cycle.slotAtRank(rank);
			InventorySlot actual = inventory.get(inventorySlot);
			if (!actual.isPotion())
			{
				continue;
			}
			BatchEntry assigned = cycle.entryAtRank(rank, actual.getPotion());
			if (assigned.getStation() == station)
			{
				present.merge(actual.getPotion(), 1, Integer::sum);
			}
		}
		for (BatchEntry entry : plan.getEntries())
		{
			if (entry.getStation() != station)
			{
				continue;
			}
			Potion potion = entry.getPotion();
			if (present.getOrDefault(potion, 0) < plan.getConfiguredCount(station, potion))
			{
				return potion;
			}
		}
		return null;
	}

	private static int countPotions(List<InventorySlot> inventory)
	{
		int count = 0;
		for (InventorySlot slot : inventory)
		{
			if (slot.isPotion())
			{
				count++;
			}
		}
		return count;
	}

	static EnumMap<Potion, Integer> potionCounts(List<InventorySlot> inventory)
	{
		EnumMap<Potion, Integer> counts = new EnumMap<>(Potion.class);
		for (InventorySlot slot : inventory)
		{
			if (slot.isPotion())
			{
				counts.merge(slot.getPotion(), 1, Integer::sum);
			}
		}
		return counts;
	}

	/**
	 * A delivered batch can roll into the next refill once only two non-MAL
	 * potions remain. MAL is deliberately ignored because retained Mixalots
	 * should carry into the next configured batch.
	 */
	static boolean shouldStartRollingRefill(List<InventorySlot> inventory)
	{
		int nonMixalotCount = 0;
		for (InventorySlot slot : inventory)
		{
			if (!slot.isPotion())
			{
				continue;
			}
			if (!slot.isFinished())
			{
				return false;
			}
			if (slot.getPotion() != Potion.MAL && ++nonMixalotCount > 2)
			{
				return false;
			}
		}
		return true;
	}

	static boolean hasMixerContents(int[] mixerSlots)
	{
		for (int slot : mixerSlots)
		{
			if (slot != 0)
			{
				return true;
			}
		}
		return false;
	}

	static Map<Station, Potion> noActiveStations()
	{
		return new EnumMap<>(Station.class);
	}
}

