package com.mixologybatch;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

@Singleton
final class LabObjectResolver
{
	private final Client client;

	@Inject
	private LabObjectResolver(Client client)
	{
		this.client = client;
	}

	TileObject find(LabObject target)
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}
		LocalPoint localPoint = LocalPoint.fromWorld(worldView, target.getLocation());
		if (localPoint == null)
		{
			return null;
		}
		Tile tile = worldView.getScene().getTiles()[worldView.getPlane()][localPoint.getSceneX()][localPoint.getSceneY()];
		if (tile == null)
		{
			return null;
		}

		for (TileObject object : tile.getGameObjects())
		{
			if (matches(object, target))
			{
				return object;
			}
		}
		if (matches(tile.getDecorativeObject(), target))
		{
			return tile.getDecorativeObject();
		}
		if (matches(tile.getWallObject(), target))
		{
			return tile.getWallObject();
		}
		if (matches(tile.getGroundObject(), target))
		{
			return tile.getGroundObject();
		}
		return null;
	}

	private static boolean matches(TileObject object, LabObject target)
	{
		return object != null && object.getId() == target.getObjectId();
	}
}

package com.mixologybatch;

import java.util.EnumMap;
import java.util.List;

final class MixPrediction
{
	private final Potion potion;
	private final int inventorySlot;
	private final EnumMap<Potion, Integer> baselineCounts;
	private final int expiresAfterTick;

	MixPrediction(
		Potion potion,
		int inventorySlot,
		EnumMap<Potion, Integer> baselineCounts,
		int expiresAfterTick)
	{
		this.potion = potion;
		this.inventorySlot = inventorySlot;
		this.baselineCounts = new EnumMap<>(baselineCounts);
		this.expiresAfterTick = expiresAfterTick;
	}

	Potion getPotion()
	{
		return potion;
	}

	int getInventorySlot()
	{
		return inventorySlot;
	}

	Potion findActualPotion(List<InventorySlot> inventory)
	{
		if (inventorySlot >= 0 && inventorySlot < inventory.size())
		{
			InventorySlot predictedSlot = inventory.get(inventorySlot);
			if (predictedSlot.isPotion())
			{
				return predictedSlot.getPotion();
			}
		}

		EnumMap<Potion, Integer> actualCounts = BatchStateResolver.potionCounts(inventory);
		for (Potion candidate : Potion.values())
		{
			if (actualCounts.getOrDefault(candidate, 0)
				> baselineCounts.getOrDefault(candidate, 0))
			{
				return candidate;
			}
		}
		return null;
	}

	boolean isExpired(int currentTick)
	{
		return currentTick > expiresAfterTick;
	}
}

